solution:
def retry(times):
    def deco(fn):
        def wrapper(*a, **kw):
            last = None
            for _ in range(times):
                try:
                    return fn(*a, **kw)
                except Exception as e:
                    last = e
            raise last
        return wrapper
    return deco

