def can_reach(begin, end, words):
    from collections import deque
    words = set(words) | {begin}
    if end not in words:
        return False
    q, seen = deque([begin]), {begin}
    while q:
        w = q.popleft()
        if w == end:
            return True
        for i in range(len(w)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                n = w[:i] + c + w[i+1:]
                if n in words and n not in seen:
                    seen.add(n)
                    q.append(n)
    return False

